package com.thrym.shared.companion

/**
 * Pixel art of the companions: full figures on an 80 x 80 grid in a 16-bit style, facing right.
 * Generated from the companion rig; change the rig and regenerate instead of editing frames.
 *
 * Every frame is one run-length encoded string, row by row from the top left: a symbol names a
 * colour in [palette] (`.` is transparent) and an optional number repeats it. Both platforms
 * draw the same pixels: Android with Compose, iOS from a bitmap built from [frame].
 */
object CompanionSprites {
    const val SIZE: Int = 80

    /** Column of the figure's centre line in a frame. Mirroring around it turns the figure without a jump. */
    const val ANCHOR_X: Int = 29

    /** Colours as ARGB, sorted from dark to light. */
    val palette: Map<Char, Int> = mapOf(
        'A' to 0xFF0E0908.toInt(),
        'B' to 0xFF0D0B12.toInt(),
