        'j' to 0xFF56535D.toInt(),
        'k' to 0xFF625245.toInt(),
        'l' to 0xFF7D4A38.toInt(),
        'm' to 0xFF5A5566.toInt(),
        'n' to 0xFF7A5A2C.toInt(),
        'o' to 0xFF9A4743.toInt(),
