        ']' to 0xFFFAD8BF.toInt(),
        '^' to 0xFFE6E2D8.toInt(),
        '_' to 0xFFC4F4FF.toInt(),
        '`' to 0xFFF6F8FB.toInt(),
        '{' to 0xFFFFFFFF.toInt()
    )

    /** How long each frame of [animation] stays on screen, in milliseconds. */
    fun durationsMs(animation: CompanionAnimation): List<Long> = when (animation) {
        CompanionAnimation.IDLE -> listOf(220L, 220L, 220L, 220L)
        CompanionAnimation.WALK -> listOf(110L, 110L, 110L, 110L, 110L, 110L)
        CompanionAnimation.ATTACK -> listOf(260L, 90L, 300L, 120L, 200L)
        CompanionAnimation.CHEER -> listOf(160L, 160L, 160L)
        CompanionAnimation.CELEBRATE -> listOf(200L, 110L, 220L, 120L, 160L, 500L)
    }

    /** Number of frames of [animation]; the same for both characters. */
    fun frameCount(animation: CompanionAnimation): Int = durationsMs(animation).size

    /** One decoded frame, cached after the first use. */
    fun frame(character: CompanionCharacter, animation: CompanionAnimation, index: Int): CompanionFrame {
        val key = Triple(character, animation, index)
        return cache.getOrPut(key) { CompanionFrame.decode(encoded(character, animation)[index], SIZE, SIZE, palette) }
    }

    private val cache = mutableMapOf<Triple<CompanionCharacter, CompanionAnimation, Int>, CompanionFrame>()

    internal fun encoded(character: CompanionCharacter, animation: CompanionAnimation): List<String> = when (character) {
        CompanionCharacter.ODIN -> when (animation) {
            CompanionAnimation.IDLE -> ODIN_IDLE
            CompanionAnimation.WALK -> ODIN_WALK
            CompanionAnimation.ATTACK -> ODIN_ATTACK
            CompanionAnimation.CHEER -> ODIN_CHEER
            CompanionAnimation.CELEBRATE -> ODIN_CELEBRATE
        }
        CompanionCharacter.VALKYRIE -> when (animation) {
            CompanionAnimation.IDLE -> VALKYRIE_IDLE
            CompanionAnimation.WALK -> VALKYRIE_WALK
            CompanionAnimation.ATTACK -> VALKYRIE_ATTACK
            CompanionAnimation.CHEER -> VALKYRIE_CHEER
            CompanionAnimation.CELEBRATE -> VALKYRIE_CELEBRATE
        }
    }

